-- "How it works" cards without client API (howitworks.lua uses it; howcore_test.lua tests it with the real data).
-- The data is howitworks_data.lua, GENERATED by server/tools/gen_howitworks_data.lua from the server configs:
--   HowData.features = [{key, title = {en, pt}, window = 'game_x'?, unlocks = [unlock key]?, goals = [goal key]?,
--                        rows = [{id, en, pt}]}]
-- A row id is one of HowCore.ROWS. pt texts are UTF-8; the module turns them into cp1252 (ChaosLocaleCore.toCp1252).
-- Lua 5.1 / LuaJIT and Lua 5.3 compatible.

HowCore = {}
local C = HowCore

-- the rows of a card, in order (the module has a tr() heading for each)
C.ROWS = { 'what', 'who', 'levels', 'drops', 'death', 'often' }

local function index(data)
  if data._index then return data._index end
  local ix = { key = {}, unlock = {}, goal = {}, window = {} }
  for _, f in ipairs(data.features or {}) do
    ix.key[f.key] = f
    for _, u in ipairs(f.unlocks or {}) do ix.unlock[u] = ix.unlock[u] or f end
    for _, g in ipairs(f.goals or {}) do ix.goal[g] = ix.goal[g] or f end
    if f.window and not ix.window[f.window] then ix.window[f.window] = f end
  end
  data._index = ix
  return ix
end

function C.find(data, key) return key and index(data).key[key] or nil end
function C.forUnlock(data, key) return key and index(data).unlock[key] or nil end
function C.forGoal(data, key) return key and index(data).goal[key] or nil end
function C.forWindow(data, module) return module and index(data).window[module] or nil end

-- 'pt-BR' (any 'pt...') picks Portuguese, everything else English
function C.langKey(lang)
  return (type(lang) == 'string' and lang:lower():sub(1, 2) == 'pt') and 'pt' or 'en'
end

-- text in the language; convert (optional) turns the UTF-8 of pt into the client font's encoding
function C.pick(t, lang, convert)
  if type(t) ~= 'table' then return '' end
  local k = C.langKey(lang)
  local s = t[k] or t.en or ''
  if k == 'pt' and convert then s = convert(s) end
  return s
end

function C.title(card, lang, convert) return C.pick(card.title, lang, convert) end

-- the rows to draw: {{id, text}} in HowCore.ROWS order, only the ones the card has
function C.rows(card, lang, convert)
  local byId, out = {}, {}
  for _, r in ipairs(card.rows or {}) do byId[r.id] = r end
  for _, id in ipairs(C.ROWS) do
    local r = byId[id]
    if r then out[#out + 1] = { id = id, text = C.pick(r, lang, convert) } end
  end
  return out
end
